mapper.select:
select ri.id, ri.room_number, ri.rent, ai.id apartment_id, ai.name, ai.introduction, ai.district_id, ai.district_name, ai.city_id, ai.city_name, ai.province_id, ai.province_name, ai.address_detail, ai.latitude, ai.longitude, ai.phone, ai.is_release from lease.room_info ri left join lease.apartment_info ai on ri.apartment_id = ai.id and ai.is_deleted = 0
ri.is_deleted = 0 and ri.is_release = 1 and not exists (select 1 from lease.lease_agreement la where la.room_id = ri.id and la.is_deleted = 0 and la.status in (1, 2, 5, 7))
and ai.province_id = #{queryVo.provinceId}
and ai.city_id = #{queryVo.cityId}
and ai.district_id = #{queryVo.districtId}
and ri.rent >= #{queryVo.minRent}
and ri.rent <= #{queryVo.maxRent}
and ri.id in ( select room_id from lease.room_payment_type where is_deleted=0 and payment_type_id=#{queryVo.paymentTypeId} )
order by ri.rent desc order by ri.rent asc
